<?php require_once __DIR__.'/includes/bootstrap.php';require_login('RSVP for this event');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: services-programs.php');exit;}check_csrf();$event=(int)($_POST['event_id']??0);$party=max(1,(int)($_POST['party_size']??1));$row=rows($pdo,'SELECT * FROM events WHERE id=? LIMIT 1',[$event])[0]??null;if(!$row){header('Location: services-programs.php?error=event');exit;}$used=(int)value($pdo,'SELECT COALESCE(SUM(party_size),0) FROM event_rsvps WHERE event_id=?',[$event]);if($used+$party>(int)($row['capacity']??PHP_INT_MAX)){header('Location: services-programs.php?error=capacity');exit;}$ref=ref_code('RSVP');$s=$pdo->prepare('INSERT INTO event_rsvps(event_id,user_id,guest_name,guest_contact,party_size,reference_code,created_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP)');$u=$_SESSION['user'];$s->execute([$event,(int)$u['id'],$u['name'],$u['email'],$party,$ref]);if(filter_var($u['email'],FILTER_VALIDATE_EMAIL))@mail($u['email'],'Barangay RSVP confirmation','Reference: '.$ref);header('Location: services-programs.php?reference='.rawurlencode($ref));exit;
